commandLine.original:
node --check js/main.js && node <<'NODE'
const fs = require('fs');
const pages = ['index.html', 'about.html', 'projects.html'];
const github = 'https://github.com/zara200814-ship-it/zara200814-ship-it.github.io';
for (const page of pages) {
  const html = fs.readFileSync(page, 'utf8');
  if (!html.includes('href="css/style.css"') || !html.includes('src="js/main.js"')) throw new Error(`${page}: missing stylesheet or script`);
  if (!html.includes(github)) throw new Error(`${page}: missing GitHub link`);
  if (!html.includes('aria-label="Main navigation"')) throw new Error(`${page}: missing navigation`);
  for (const [, href] of html.matchAll(/href="(\.\.?\/[^"#?]+|[^"#?]+\.html)"/g)) {
    if (!fs.existsSync(require('path').join(require('path').dirname(page), href))) throw new Error(`${page}: broken local link ${href}`);
  }
}
for (const path of ['css/style.css', 'js/main.js', 'assets/images']) {
  if (!fs.existsSync(path)) throw new Error(`Missing ${path}`);
}
console.log('Portfolio files and local page links validated.');
NODE

